import {COUNTRY,DISPLAY_ROSTER,TALENTS} from './data.js?v=187';
import {GAME_MODES,draftCountry} from './game-setup.js?v=187';
import {brand,button,flag,esc,icon,portrait,talentIcon} from './ui.js?v=187';
import {recruitCard,recruitControls,visibleRecruits} from './recruit-selection.js?v=187';
import {teamBalanceMarkup} from './team-balance.js?v=187';

export function gameModeControl(mode='regular',multi=false,enabled=true){return `<label class="game-mode-control">Mode de jeu<select id="${multi?'mpGameMode':'gameMode'}" ${enabled?'':'disabled'}>${Object.entries(GAME_MODES).map(([id,label])=>`<option value="${id}" ${mode===id?'selected':''}>${label}</option>`).join('')}</select></label>`;}
export function orderedTeamMarkup(ids,{multi=false,editable=true}={}){
 const prefix=multi?'mp-draft':'solo-draft';
 return `<div class="draft-team-order" aria-label="Ordre de votre équipe ; premier agent chef">${ids.map((id,i)=>{const a=DISPLAY_ROSTER.find(a=>a.id===id);return `<article class="draft-team-agent">${portrait(a)}<div><strong>${esc(a.name)}</strong><small>${i===0?'Chef · Coordination +5':'Agent '+(i+1)}</small></div><div class="draft-order-actions">${button(icon('crown'),prefix+'-chief','small',`data-id="${id}" aria-label="Désigner ${esc(a.name)} chef" ${!editable||i===0?'disabled':''}`)}${button('↑',prefix+'-before','small',`data-id="${id}" aria-label="Avancer ${esc(a.name)}" ${!editable||i===0?'disabled':''}`)}${button('↓',prefix+'-after','small',`data-id="${id}" aria-label="Reculer ${esc(a.name)}" ${!editable||i===3?'disabled':''}`)}</div></article>`;}).join('')}</div>`;
}
export function draftTeamSummary(ids,country){
 const agents=ids.map(id=>DISPLAY_ROSTER.find(a=>a.id===id)).filter(Boolean),counts=new Map();
 for(const a of agents)for(const t of a.talents)counts.set(t,(counts.get(t)||0)+1);
 const selectedTalents=[...counts].sort(([a],[b])=>TALENTS[a][0].localeCompare(TALENTS[b][0],'fr',{sensitivity:'base'}));
 return `<aside class="draft-summary panel" aria-label="Composition et valeurs de votre équipe"><h2>Votre équipe · ${esc(COUNTRY[country].name)}</h2><p class="draft-summary-count" role="status">${agents.length} / 4 agents repêchés</p><div class="draft-summary-agents">${Array.from({length:4},(_,i)=>{const a=agents[i];return a?`<div class="draft-summary-agent">${portrait(a)}<strong>${esc(a.name)}</strong><small>${esc(a.role)}</small></div>`:`<div class="draft-summary-agent empty"><span>${i+1}</span><small>À choisir</small></div>`;}).join('')}</div>${teamBalanceMarkup(ids)}<section class="draft-summary-talents"><h3>Talents repêchés · ${counts.size}</h3>${selectedTalents.length?`<div class="talents">${selectedTalents.map(([id,count])=>`<span title="${esc(TALENTS[id][1])}" data-talent="${id}">${talentIcon(id)}${esc(TALENTS[id][0])}${count>1?` <b>×${count}</b>`:''}</span>`).join('')}</div>`:'<p>Aucun talent pour le moment.</p>'}</section></aside>`;
}
export function draftScreen(d,country,{multi=false,header='',agents=d.teams[country]||[],confirmed=false,editable=true,controls=''}={}){
 const mode=multi?'multi':'solo',current=draftCountry(d),finished=!current,canPick=editable&&current===country,owners=new Map(d.picks.map(p=>[p.id,p.country]));
 const status=finished?'Repêchage terminé · choisissez votre chef':`Tour de ${COUNTRY[current].name} · ronde ${Math.floor(d.picks.length/4)+1}/4 · choix ${d.picks.length+1}/16`;
 const countries=`<section class="draft-countries" aria-label="Ordre du repêchage">${d.order.map((c,i)=>`<article class="panel draft-country ${c===current?'current':''} ${c===country?'own':''}"><header><span class="draft-position">${i+1}</span>${flag(c)}<div><strong>${COUNTRY[c].name}</strong><small>${d.humans.includes(c)?'Joueur':'PNJ'}${c===country?' · Vous':''}</small></div></header><ul>${d.teams[c].map(id=>`<li>${esc(DISPLAY_ROSTER.find(a=>a.id===id).name)}</li>`).join('')}${Array.from({length:4-d.teams[c].length},()=>'<li class="muted">À choisir</li>').join('')}</ul></article>`).join('')}</section>`;
 const content=finished?(country?`<div class="draft-final-team"><section class="panel"><h2>Votre équipe · ${COUNTRY[country].name}</h2><p>Le premier agent est votre chef. Réorganisez vos agents, puis confirmez votre équipe.</p>${orderedTeamMarkup(agents,{multi,editable})}${button(confirmed?'Équipe confirmée ✓':'Confirmer mon équipe',multi?'mp-team':'solo-confirm-team','primary wide',confirmed||!editable?'disabled':'')}${!multi?button('Lancer l’opération','start','primary wide',!confirmed?'disabled':''):''}</section>${draftTeamSummary(agents,country)}</div>`:'<p class="notice">Les joueurs choisissent leur chef et confirment leur équipe.</p>'):`<div class="draft-selection"><div class="draft-catalog"><p class="notice draft-turn" role="status">${canPick?'À vous de choisir un agent.':'En attente du choix de '+COUNTRY[current].name+'.'}</p>${recruitControls(mode)}<div class="recruit-grid draft-recruits">${visibleRecruits(mode).map(a=>`<div class="draft-candidate ${owners.has(a.id)?'taken':''}">${recruitCard(a,d.teams[country]||[],mode,{cmd:multi?'mp-draft-pick':'solo-draft-pick',disabled:!canPick||owners.has(a.id)})}${owners.has(a.id)?`<span class="draft-owner">${flag(owners.get(a.id))} ${COUNTRY[owners.get(a.id)].name}</span>`:''}</div>`).join('')}</div></div>${country?draftTeamSummary(d.teams[country]||[],country):''}</div>`;
 return `<div class="setup-shell draft-shell"><header>${brand()}<div class="classified">MODE AVANCÉ</div></header><main class="setup-main">${header}<div class="draft-heading"><div><span class="eyebrow">REPÊCHAGE EN SERPENTIN · ${d.picks.length}/16 AGENTS</span><h1>${status}</h1><p>Ordre des rondes : 1 → 4, 4 → 1, 1 → 4, 4 → 1. Vingt agents disponibles, seize retenus. Chaque agent appartient à un seul pays.</p></div>${controls}</div>${countries}${content}</main></div>`;
}
